<script lang="ts">
 import type {AppData} from '#lib/client/types.ts';
 import {sourceHref} from '#lib/client/source-links.ts';
  import type {Row} from '#lib/client/types.ts';
  import {display} from '#lib/client/api.ts';
  import {reportList,reportNumber,reportQuantity} from '#lib/client/reports.ts';
  import Icon from '../Icon.svelte';
  import ReportComparison from './ReportComparison.svelte';
  let {data,capacity,materials,risks,canDispatch=false,period}:{data:AppData;capacity:Row[];materials:Row[];risks:Row[];canDispatch?:boolean;period?:Row}=$props();
  const unitName=(unit:string)=>({piece:'Stück',m2:'m²',m3:'m³',h:'Std.'} as Record<string,string>)[unit]||unit||'';
</script>
<section class="panel"><header class="panel-header"><div><h2>Verfügbare Kapazität je Team & Woche</h2><p>Vertragliche Stunden, bestätigte Abwesenheiten und Auftragsplanung im Zusammenhang.{#if period?.from&&period?.to} {display(period.from,'date')} bis {display(period.to,'date')}; bei langen Berichten die letzten zwölf Wochen.{/if}</p></div>{#if canDispatch}<a class="btn small" href={sourceHref(data,'/dispatch')}>Disposition öffnen<Icon name="arrow" size={14}/></a>{/if}</header><div class="panel-body"><p class="small">Die Übersicht dient der Einsatzplanung. Sie enthält keine Rangliste einzelner Mitarbeitender. Ohne bestätigtes Arbeitsmodell bleibt die verfügbare Kapazität unbekannt.</p></div>
{#if capacity.length}<ReportComparison rows={capacity.map(row=>({...row,label:(row.team_name||'Team')+' · Woche ab '+display(row.week_start,'date')}))} fields={[{key:'contract_hours',label:'Vertraglich',color:'#a6b39b'},{key:'available_hours',label:'Verfügbar',color:'#4b7252'},{key:'planned_hours',label:'Geplant',color:'#b29160'}]} unit="Std." caption="Kapazität und Planung nach Team und Woche"/><div class="table-scroll"><table class="data-table"><caption class="sr-only">Kapazitätsplanung in Stunden je Team und Woche</caption><thead><tr><th>Team / Woche ab</th><th class="number">Vertraglich</th><th class="number">Verfügbar</th><th class="number">Geplant</th><th>Planungslage</th></tr></thead><tbody>{#each capacity as row}<tr><th scope="row">{row.team_name||'Team'}<span class="record-subtitle">{display(row.week_start,'date')}</span></th><td class="number">{reportQuantity(row.contract_hours,'Std.')}</td><td class="number">{reportQuantity(row.available_hours,'Std.')}</td><td class="number">{reportQuantity(row.planned_hours,'Std.')}</td><td>{#if reportList(row.issues).length}{#each reportList(row.issues) as issue}<p class="capacity-issue">{typeof issue==='string'?issue:issue.message||issue.label||issue.title}</p>{/each}{:else if reportNumber(row.available_hours)===null||reportNumber(row.planned_hours)===null}Planungsgrundlagen unvollständig{:else if Number(row.planned_hours)>Number(row.available_hours)}<span class="capacity-issue">Über der bestätigten Kapazität</span>{:else}Innerhalb der bestätigten Kapazität{/if}{#if row.href}<a class="text-link mt" href={sourceHref(data,row.href)}>Plan öffnen<Icon name="arrow" size={13}/></a>{/if}</td></tr>{/each}</tbody></table></div>{:else}<div class="empty-state compact"><Icon name="calendar" size={27}/><h3>Noch keine bestätigte Kapazitätsreihe</h3><p>Arbeitsmodelle, Beschäftigungszeiträume, Jahreskalender und geplante Einsätze bilden die Grundlage.</p></div>{/if}</section>
<section class="panel mt"><header class="panel-header"><div><h2>Materialbedarf & erwarteter Bestand</h2><p>Gleichzeitige Bedarfe werden zusammengefasst. Bestand und bestätigte Liefermengen decken jeden Bedarf nur einmal.</p></div></header><div class="panel-body"><p class="small">Die Vorschau verwendet den aktuellen bestätigten Bestand{materials[0]?.stock_as_of?' vom '+display(materials[0].stock_as_of,'date'):''}. Bereits verbrauchte Mengen sind abgezogen. Frühe Bedarfe werden vor späteren gedeckt; diese Vorschau reserviert oder bucht nichts. Bei historischen Zeiträumen ist sie kein historischer Inventurnachweis.</p></div>{#if materials.length}<div class="table-scroll"><table class="data-table"><caption class="sr-only">Materialbedarf mit Termin, Einheit und bestätigten Zuläufen</caption><thead><tr><th>Material / benötigt am</th><th class="number">Gesamtbedarf</th><th class="number">Noch offen</th><th class="number">Aus Bestand gedeckt</th><th class="number">Bestätigter Zulauf</th><th class="number">Fehlmenge</th><th>Quelle / Klärung</th></tr></thead><tbody>{#each materials as row}<tr><th scope="row">{row.product_name||'Material'}<span class="record-subtitle">{display(row.required_at,'date')}</span></th><td class="number">{reportQuantity(row.required_quantity,unitName(row.unit))}<span class="record-subtitle">Verbraucht: {reportQuantity(row.consumed_quantity,unitName(row.unit))}</span></td><td class="number">{reportQuantity(row.outstanding_quantity,unitName(row.unit))}<span class="record-subtitle">Bis Termin kumuliert: {reportQuantity(row.cumulative_required_quantity,unitName(row.unit))}</span></td><td class="number">{reportQuantity(row.expected_stock,unitName(row.unit))}</td><td class="number">{reportQuantity(row.confirmed_supply,unitName(row.unit))}</td><td class="number capacity-issue">{reportQuantity(row.shortage,unitName(row.unit))}</td><td>{#if row.order_names?.length}<p class="small mb">{row.order_names.join(' · ')}</p>{/if}{#each reportList(row.issues) as issue}<p class="capacity-issue">{typeof issue==='string'?issue:issue.message||issue.label||issue.title}</p>{/each}{#if row.href}<a class="text-link" href={sourceHref(data,row.href)}>Bedarf prüfen<Icon name="arrow" size={13}/></a>{:else}Kein vollständiger Quellennachweis{/if}</td></tr>{/each}</tbody></table></div>{:else}<div class="empty-state compact"><Icon name="box" size={27}/><h3>Materialvorschau noch nicht bestätigt</h3><p>Unbekannte Liefertermine und unbestätigte Liefermengen werden nicht als gesicherter Bestand behandelt.</p></div>{/if}</section>
<section class="panel mt"><header class="panel-header"><div><h2>Aufträge mit Klärungsbedarf</h2><p>Konkrete Gründe und die nächste mögliche Prüfung.</p></div></header><div class="panel-body">{#each risks as order}<article class="risk-order"><a class="text-link" href={sourceHref(data,`/orders/${order.order_id}`)}>{order.order_number||'Auftrag'} · {order.title||'Stand prüfen'}<Icon name="arrow" size={14}/></a><ul>{#each reportList(order.reasons) as reason}<li>{#if reason.href}<a href={sourceHref(data,reason.href)}>{reason.label||reason.message||reason.title}<Icon name="arrow" size={13}/></a>{:else}{reason.label||reason.message||reason.title||'Grundlage prüfen'}{/if}</li>{/each}</ul></article>{/each}{#if !risks.length}<p class="small">Aktuell sind keine begründeten Risikohinweise gemeldet. Eine leere Liste bestätigt noch keine vollständigen Daten oder gesicherten Liefertermine.</p>{/if}</div></section>
<style>.capacity-issue{color:var(--warning);font-size:12px}.capacity-issue+.capacity-issue{margin-top:6px}.risk-order+.risk-order{border-top:1px solid var(--line);padding-top:22px;margin-top:22px}.risk-order>.text-link{font-size:14px}.risk-order ul{padding-left:18px;margin-top:12px;font-size:12px;color:var(--muted)}.risk-order li+li{margin-top:8px}.risk-order li a{display:inline-flex;align-items:center;gap:6px;color:var(--forest)}@media(max-width:760px){.panel-header{flex-wrap:wrap}.capacity-issue,.risk-order ul{font-size:13px}.risk-order>.text-link{font-size:15px}}</style>
